// Parse LLM response (multi-item safe)
const out = [];
for (const item of $input.all()) {
  const email = item.json;
  let classification = {};
  try {
    const text = email.text || email.response || '{}';
    const jsonMatch = text.match(/\{[\s\S]*\}/);
    classification = jsonMatch ? JSON.parse(jsonMatch[0]) : JSON.parse(text);
  } catch (e) {
    classification = {
      intent: 'informational', confidence: 0.3, urgency_score: 3,
      sentiment: 'neutral', entities: { deadlines: [], action_items: [], people_mentioned: [], projects: [] },
      suggested_action: 'archive', summary: 'Failed to classify', parseError: true
    };
  }
  if (classification.confidence < 0.7) {
    const subject = (email.subject || '').toLowerCase();
    if (subject.includes('urgent') || subject.includes('asap')) {
      classification.intent = 'urgent'; classification.urgency_score = 9;
    }
    if (subject.includes('unsubscribe') || subject.includes('newsletter')) {
      classification.intent = 'newsletter';
    }
  }
  out.push({ json: { ...email, classification, routingDecision: classification.suggested_action || 'archive' } });
}
return out;

