// Extract dates from email content
const email = $input.first().json;
const text = (email.textContent || '').toLowerCase();
const datePatterns = [
  /(monday|tuesday|wednesday|thursday|friday|saturday|sunday)[,\s]+(\w+)[,\s]+(\d{1,2})/gi,
  /(\d{1,2})[\/\-\.](\d{1,2})[\/\-\.](\d{2,4})/g,
  /(\d{1,2}):(\d{2})\s*(am|pm)/gi
];
const extractedDates = [];
datePatterns.forEach(p => {
  const matches = text.match(p);
  if (matches) extractedDates.push(...matches);
});
return [{ json: { ...email, extractedDates: extractedDates.slice(0, 3), calendarAction: extractedDates.length > 0 ? 'review_needed' : 'no_dates_found' } }];

// Log execution for analytics (one entry per item, context-safe)
const results = [];
for (const item of $input.all()) {
  const data = item.json;
  const logEntry = {
    executionId: $execution.id,
    timestamp: new Date().toISOString(),
    messageId: data.messageId || data.id || null,
    sender: data.senderEmail || null,
    subject: (data.subject || '').substring(0, 100),
    intent: data.classification?.intent || 'unknown',
    confidence: data.classification?.confidence || 0,
    urgencyScore: data.classification?.urgency_score || 0,
    actionTaken: data.routingDecision || 'none',
    skipped: data.skipped === true,
    success: true,
  };
  console.log('ANALYTICS_LOG:', JSON.stringify(logEntry));
  results.push({ json: logEntry });
}
return results;
